'use strict';
modules.splice(1,0,['projects','▦','Meus projetos'],['skins','◧','Galeria de skins']);modules.push(['security','◇','Proteção & acesso']);
const previousRender=render,previousStudio=studio;
function activeBrand(){return project()?.brand||state.brand}
project=()=>state.projects.find(p=>p.id===state.activeProjectId)||state.projects[0];
function migrateWorkspace(){state.personalSkins??=[];state.activeProjectId??=state.projects[0]?.id;for(const p of state.projects){p.brand??=structuredClone(state.brand);p.layoutId??='executive';p.layout??=structuredClone(skinById(p.layoutId).layout);p.surface??={opacity:85,blur:10,radius:6};p.contact??={site:'',whatsapp:'',instagram:''};p.brief??={goal:'',audience:'',notes:''};}document.querySelector('.badge').textContent='PROTÓTIPO FUNCIONAL · V0.2';}
render=()=>{migrateWorkspace();previousRender();if(!document.getElementById('encrypted-backup')){const btn=document.createElement('button');btn.id='encrypted-backup';btn.textContent='◇ Backup criptografado';btn.onclick=encryptedBackupForm;$('#backup').after(btn)}};
studio=()=>{previousStudio();const p=project();if(!p)return;const tools=document.createElement('div');tools.className='project-context';tools.innerHTML=`<a href="#projects">← Meus projetos</a><span>Projeto individual · ${escapeHTML(p.client)}</span><button class="small" id="open-skin-gallery">◧ Trocar skin</button>`;$('#main').prepend(tools);bind('open-skin-gallery','click',()=>{editorTab='skins';studio()});if(!$$('[data-etab="skins"]').length){const tab=document.createElement('button');tab.textContent='Skins';tab.dataset.etab='skins';tab.className=editorTab==='skins'?'active':'';tab.onclick=()=>{editorTab='skins';studio()};$('.editorbar').insertBefore(tab,$('.editorbar').children[1]);}if(editorTab==='skins'){renderSkinLibrary($('#editor-settings'));}if(editorTab==='aparencia'){const extra=document.createElement('div');extra.innerHTML=`<hr class="divider"><h3>Identidade deste projeto</h3><p class="muted">A marca e os contatos abaixo pertencem somente a este cliente.</p><form id="project-brand-form" class="formgrid">${field('Nome da empresa *','project-brand-name',p.brand.name,'text','required')}${field('Cor de destaque','project-brand-color',p.brand.color,'color')}<label>Logotipo deste projeto<input id="project-logo" type="file" accept="image/png,image/jpeg,image/webp"></label>${field('Site oficial','project-site',p.contact.site,'url')}${field('WhatsApp — URL HTTPS','project-whatsapp',p.contact.whatsapp,'url')}${field('Instagram — URL HTTPS','project-instagram',p.contact.instagram,'url')}<label class="full">Objetivo do projeto<textarea id="project-goal">${escapeHTML(p.brief.goal)}</textarea></label><div class="full"><button class="dark" type="submit">Salvar identidade do projeto</button></div></form><hr class="divider"><h3>Acabamento da composição</h3><div class="formgrid"><label>Opacidade do painel<input id="surface-opacity" type="range" min="25" max="100" value="${p.surface.opacity}"></label><label>Desfoque do vidro<input id="surface-blur" type="range" min="0" max="24" value="${p.surface.blur}"></label><label>Cantos discretos<input id="surface-radius" type="range" min="0" max="24" value="${p.surface.radius}"></label><div><p class="muted">Fonte do workspace: sistema operacional. A família licenciada de cada cliente deve ser fornecida para integração final.</p></div></div>`;$('#editor-settings').append(extra);bind('project-brand-form','submit',async e=>{e.preventDefault();let logo=p.brand.logo;const f=$('#project-logo').files[0];if(f){if(f.size>2*1024*1024)return toast('Use logotipo de até 2 MB.');logo=await readData(f)}p.brand={...p.brand,name:$('#project-brand-name').value.trim(),color:$('#project-brand-color').value,logo};p.contact={site:$('#project-site').value.trim(),whatsapp:$('#project-whatsapp').value.trim(),instagram:$('#project-instagram').value.trim()};p.brief.goal=$('#project-goal').value;await save();studio();toast('Identidade salva somente neste projeto.');});for(const [id,key]of[['surface-opacity','opacity'],['surface-blur','blur'],['surface-radius','radius']])bind(id,'input',e=>{p.surface[key]=+e.target.value;applySkin();save()});}applySkin();};
function geometry(el,box){const[x,y,w,h]=box;el.style.left=x+'%';el.style.top=y+'%';el.style.width=w+'%';el.style.height=h+'%';el.style.right='auto';el.style.bottom='auto';el.style.transform='none'}
applySkin=()=>{const p=project();if(!p||!$('#stage'))return;const skin=skinById(p.layoutId),layout=p.layout||skin.layout,brand=activeBrand(),surface=p.surface||{opacity:85,blur:10,radius:6};$('#stage').dataset.layout=p.layoutId;const panel=p.panel||skin.panel,light=panel==='#f1e9e2';const style=el=>{el.style.background=panel+Math.round(surface.opacity*2.55).toString(16).padStart(2,'0');el.style.backdropFilter=`blur(${surface.blur}px)`;el.style.borderRadius=surface.radius+'px';el.style.color=light?'#293a32':'white';el.style.border='1px solid '+brand.color+'66';};const bar=$('#skinbar');geometry(bar,layout.brand);style(bar);bar.style.maxWidth='none';const dock=$('.skindock');geometry(dock,layout.dock);style(dock);dock.style.flexDirection=layout.dock[2]<layout.dock[3]?'column':'row';dock.style.justifyContent='space-around';dock.style.alignItems='center';dock.querySelectorAll('button').forEach(b=>{b.style.color=light?'#243b32':'white';b.style.padding='4px';b.style.minWidth='22px';b.style.minHeight='22px'});$('#skin-scene-chip')?.remove();const chip=document.createElement('div');chip.id='skin-scene-chip';chip.className='skin-scene-chip';chip.textContent=currentScene()?.name||p.name;$('#stage').append(chip);geometry(chip,layout.scene);style(chip);$('#skin-scene-menu')?.remove();const menu=document.createElement('button');menu.id='skin-scene-menu';menu.className='skin-scene-menu';menu.textContent='☰ Ambientes';menu.onclick=openScenePanel;$('#stage').append(menu);geometry(menu,layout.menu);style(menu);$('#project-contact-buttons')?.remove();const contacts=document.createElement('div');contacts.id='project-contact-buttons';contacts.className='project-contact-buttons';for(const [key,label]of[['site','Site'],['whatsapp','Contato'],['instagram','Instagram']]){const u=safeURL(p.contact?.[key]);if(u){const a=document.createElement('a');a.href=u;a.textContent=label;a.target='_blank';a.rel='noopener noreferrer';contacts.append(a)}}$('#stage').append(contacts);};
function openScenePanel(){if($('#scene-panel'))return;const p=project(),panel=document.createElement('div');panel.id='scene-panel';panel.className='scene-panel';panel.innerHTML=`<div class="actions"><h3>Ambientes</h3><button class="small" id="close-scene-panel" aria-label="Fechar ambientes">×</button></div>${p.scenes.map((s,i)=>`<button data-panel-scene="${i}">${i+1}. ${escapeHTML(s.name)}</button>`).join('')||'<p>Importe os ambientes do projeto.</p>'}`;$('#stage').append(panel);bind('close-scene-panel','click',()=>panel.remove());$$('[data-panel-scene]').forEach(b=>b.onclick=()=>{const index=+b.dataset.panelScene;selectScene(index);openScenePanel()})}
newProject=async(templateId='executive')=>{if(typeof templateId!=='string')templateId='executive';const skin=skinById(templateId);modal(`<div class="eyebrow">PROJETO INDIVIDUAL</div><h2>Uma experiência só deste cliente.</h2><p>Modelo inicial: ${escapeHTML(skin.name)}. Identidade, contatos e arquivos de clientes anteriores não são transferidos.</p><form id="new-project-v2" class="formgrid">${field('Nome do projeto *','new-project-name','','text','required maxlength="100"')}${field('Empresa / cliente *','new-project-client','','text','required maxlength="100"')}<label class="full">Objetivo inicial<textarea id="new-project-goal" placeholder="O que essa experiência precisa ajudar o visitante a fazer?"></textarea></label><label class="full">Modelo inicial<select id="new-project-template">${MG_SKINS.map(s=>`<option value="${s.id}" ${s.id===skin.id?'selected':''}>${escapeHTML(s.name)}</option>`).join('')}</select></label><div class="full"><button class="dark" type="submit">Criar projeto individual</button></div></form>`);bind('new-project-v2','submit',async e=>{e.preventDefault();const model=skinById($('#new-project-template').value),client=$('#new-project-client').value.trim();const p={id:uid(),name:$('#new-project-name').value.trim(),client,status:'Rascunho',skin:'faixa',layoutId:model.id,layout:structuredClone(model.layout),panel:model.panel,transition:'fade',scenes:[],floorplan:'',pins:[],brand:{name:client,signature:'',color:model.color,logo:''},surface:{opacity:85,blur:10,radius:model.radius},contact:{site:'',whatsapp:'',instagram:''},brief:{goal:$('#new-project-goal').value.trim(),audience:'',notes:''},createdAt:new Date().toISOString()};state.projects.push(p);state.activeProjectId=p.id;await save();sceneIndex=0;editorTab='aparencia';closeModal();go('studio');if(activeRoute==='studio')studio()});};
function projectsPage(){$('#main').innerHTML=title('CRIAÇÃO · MEUS PROJETOS','Cada cliente, uma experiência própria.','Projetos independentes, com identidade, cenas, pontos e briefing separados.',`<button class="dark" id="new-individual-project">+ Projeto individual</button><button id="choose-project-skin">Escolher um modelo</button>`)+`<div class="sectionhead"><h2>${state.projects.length} projetos</h2><input id="project-search" class="search" placeholder="Buscar projeto ou cliente" aria-label="Buscar projeto"></div><div id="projects-grid" class="grid"></div>${notice('A separação desta versão é local, dentro do mesmo workspace. Permissões de usuários e isolamento no servidor ainda não implementados.')}`;const list=(q='')=>{$('#projects-grid').innerHTML=state.projects.filter(p=>(p.name+' '+p.client).toLowerCase().includes(q.toLowerCase())).map(p=>{const skin=skinById(p.layoutId);return`<article class="card project-card"><div class="layout-thumb">${layoutThumb({...skin,id:skin.id+'-'+p.id,layout:p.layout||skin.layout})}</div><span class="tag">${escapeHTML(p.client)}</span><h3>${escapeHTML(p.name)}</h3><p>${p.scenes.length} ambientes · ${p.scenes.reduce((n,s)=>n+s.hotspots.length,0)} pontos<br>${escapeHTML(p.status)}</p><div class="actions"><button data-open-project="${p.id}">Abrir projeto ↗</button><button data-copy-project="${p.id}">Duplicar</button></div></article>`}).join('')||'<div class="panel"><h2>Seu próximo projeto começa aqui.</h2><p>Escolha uma skin ou comece um projeto individual.</p></div>';$$('[data-open-project]').forEach(b=>b.onclick=async()=>{state.activeProjectId=b.dataset.openProject;sceneIndex=0;await save();go('studio')});$$('[data-copy-project]').forEach(b=>b.onclick=async()=>{const original=state.projects.find(p=>p.id===b.dataset.copyProject),copy=structuredClone(original),map=new Map(copy.scenes.map(s=>[s.id,uid()]));copy.id=uid();copy.name+=' — cópia';copy.status='Rascunho';copy.scenes.forEach(s=>{s.id=map.get(s.id);s.hotspots.forEach(h=>{h.id=uid();if(h.type==='scene')h.target=map.get(h.target)||h.target})});copy.pins.forEach(pin=>pin.scene=map.get(pin.scene)||pin.scene);state.projects.push(copy);await save();projectsPage();toast('Cópia independente criada.');})};list();bind('project-search','input',e=>list(e.target.value));bind('new-individual-project','click',()=>newProject());bind('choose-project-skin','click',()=>go('skins'));}
function skinsPage(){$('#main').innerHTML=title('CRIAÇÃO · GALERIA DE SKINS','A experiência começa pela composição.','15 layouts próprios, orientados por referências reais da MG Tour.')+`<div id="full-skin-library"></div>`;renderSkinLibrary($('#full-skin-library'));}
function renderSkinLibrary(root){const p=project();root.innerHTML=`<section class="my-skins"><div><h2>Minhas skins</h2><p>Guarde composição, painéis, cores e transparência. Nome, logotipo, contatos e panoramas ficam no projeto.</p></div><div class="actions"><input id="my-skin-name" placeholder="Nome do meu layout" aria-label="Nome da minha skin"><button id="save-personal-skin" ${p?'':'disabled'}>Salvar visual atual</button><button id="import-skin-collection">Importar coleção</button><button id="export-skin-collection" ${state.personalSkins.length?'':'disabled'}>Exportar coleção</button><input type="file" id="skin-collection-file" accept=".json,application/json" hidden></div><div class="personal-skin-list">${state.personalSkins.map(s=>`<button data-personal-skin="${s.id}">${escapeHTML(s.name)}</button>`).join('')||'<span class="muted">Sua coleção ainda está vazia.</span>'}</div></section><div class="sectionhead"><h2>Catálogo · 15 composições</h2><div class="actions"><input id="skin-search" placeholder="Buscar skin ou projeto" aria-label="Buscar skin"><select id="skin-family" aria-label="Filtrar skins por segmento"><option value="">Todos os segmentos</option>${[...new Set(MG_SKINS.map(s=>s.family))].map(f=>`<option>${f}</option>`).join('')}</select></div></div><p class="muted">As miniaturas mostram a nova composição. “Ver referência” abre a captura histórica do projeto que orientou o layout. Variações próprias estão identificadas.</p><div id="skin-catalog-grid" class="skin-grid"></div><section class="panel"><h3>Outros registros encontrados no histórico</h3><p class="muted">Castro Car Skin 2026, M3 Veículos, Armazém Vida Saudável, AVA/Dorata e Babitonga. A importação de seus pacotes e a conferência visual continuam pendentes nesta galeria; não estão contados como layouts recuperados.</p></section>`;function list(){const q=$('#skin-search').value.toLowerCase(),family=$('#skin-family').value;$('#skin-catalog-grid').innerHTML=MG_SKINS.filter(s=>(!family||s.family===family)&&(s.name+' '+s.reference+' '+s.family).toLowerCase().includes(q)).map(s=>`<article class="skin-card ${p?.layoutId===s.id?'selected':''}"><div class="layout-thumb">${layoutThumb(s)}</div><div class="skin-card-body"><div class="meta"><span class="tag">${s.family}</span>${p?.layoutId===s.id?'<span class="status">Aplicada</span>':''}</div><h3>${s.name}</h3><p>${s.description}</p><small>Referência: ${s.reference}</small><small>${s.origin}</small><div class="actions"><button data-skin-reference="${s.id}">Ver referência</button><button data-skin-apply="${s.id}" class="dark">${p?'Aplicar no projeto':'Criar projeto'}</button><button data-skin-new="${s.id}" class="small">+ Novo com este layout</button></div></div></article>`).join('');$$('[data-skin-reference]').forEach(b=>b.onclick=()=>{const s=skinById(b.dataset.skinReference);modal(`<div class="eyebrow">REFERÊNCIA HISTÓRICA · CAPTURA LOCAL</div><h2>${escapeHTML(s.reference)}</h2><img class="reference-image" src="references/${s.image}.jpg" alt="Referência ${escapeHTML(s.reference)}"><p>${escapeHTML(s.origin)}. Esta imagem documenta o projeto anterior; não é uma captura atual do tour online.</p><p class="muted">O modelo aplica uma composição própria. Recursos como tradução, guia, mapa 3D, pavimentos ou VLibras continuam dependendo de integração específica.</p>`) });$$('[data-skin-apply]').forEach(b=>b.onclick=async()=>{if(!project())return newProject(b.dataset.skinApply);await applyPreset(skinById(b.dataset.skinApply));if(activeRoute==='studio')studio();else{list();toast('Skin aplicada ao projeto '+project().name+'.')}});$$('[data-skin-new]').forEach(b=>b.onclick=()=>newProject(b.dataset.skinNew));}list();bind('skin-search','input',list);bind('skin-family','change',list);bind('save-personal-skin','click',async()=>{const name=$('#my-skin-name').value.trim();if(!name)return toast('Dê um nome ao visual.');if(state.personalSkins.length>=50)return toast('Limite local de 50 skins pessoais.');const p=project();state.personalSkins.push({id:uid(),name,baseId:p.layoutId,layout:structuredClone(p.layout),panel:p.panel||skinById(p.layoutId).panel,color:p.brand.color,surface:structuredClone(p.surface)});await save();renderSkinLibrary(root);toast('Composição salva sem dados do cliente.');});bind('export-skin-collection','click',()=>download('mg-tour-minhas-skins.json',JSON.stringify({schema:'mgtour360.skins/v1',skins:state.personalSkins},null,2)));bind('import-skin-collection','click',()=>$('#skin-collection-file').click());bind('skin-collection-file','change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1024*1024)throw Error('Coleção deve ter até 1 MB.');const input=JSON.parse(await file.text());if(input.schema!=='mgtour360.skins/v1'||!Array.isArray(input.skins)||input.skins.length>50)throw Error('Formato inválido.');const imported=input.skins.map(validatePersonalSkin);state.personalSkins=[...state.personalSkins,...imported].slice(0,50);await save();renderSkinLibrary(root);toast('Coleção importada e validada.')}catch(err){toast('Coleção recusada: '+err.message)}});$$('[data-personal-skin]').forEach(b=>b.onclick=async()=>{if(!project())return toast('Crie ou abra um projeto antes de aplicar.');const s=state.personalSkins.find(s=>s.id===b.dataset.personalSkin);await applyPreset({...skinById(s.baseId),layout:s.layout,panel:s.panel,color:s.color,radius:s.surface.radius,surface:s.surface});if(activeRoute==='studio')studio();else list();toast('Visual pessoal aplicado.');});}
async function applyPreset(s){const p=project();p.layoutId=s.id;p.layout=structuredClone(s.layout);p.panel=s.panel;p.surface=structuredClone(s.surface||{opacity:85,blur:10,radius:s.radius});p.status='Em edição';await save();}
function validatePersonalSkin(s){if(!s||typeof s.name!=='string'||!s.layout)throw Error('Skin sem nome ou composição.');const hex=/^#[0-9a-f]{6}$/i;if(!hex.test(s.panel)||!hex.test(s.color))throw Error('Cores inválidas.');const layout={};for(const key of['brand','scene','dock','menu']){const a=s.layout[key];if(!Array.isArray(a)||a.length!==4||a.some(n=>typeof n!=='number'||!Number.isFinite(n)||n<0||n>100)||a[2]<5||a[3]<5||a[0]+a[2]>100||a[1]+a[3]>100)throw Error('Geometria inválida.');layout[key]=a.slice()}return{id:uid(),name:s.name.slice(0,80),baseId:skinById(s.baseId).id,layout,panel:s.panel,color:s.color,surface:{opacity:Math.max(25,Math.min(100,Number(s.surface?.opacity)||85)),blur:Math.max(0,Math.min(24,Number(s.surface?.blur)||0)),radius:Math.max(0,Math.min(24,Number(s.surface?.radius)||0))}};}
function securityPage(){$('#main').innerHTML=title('ARQUITETURA · PROTEÇÃO & ACESSO','Proteção com limites claros.','O acesso ao produto, aos dados e ao código exige camadas diferentes.')+`<div class="grid"><article class="card"><div class="icon">◇</div><h3>Backup protegido por senha</h3><p>AES-GCM de 256 bits, chave derivada da sua senha e salt aleatório. A senha não é gravada.</p><button id="security-export">Criar backup criptografado ↗</button></article><article class="card"><div class="icon">▦</div><h3>Dados por projeto</h3><p>Cenas, marca, contatos, composição e briefing separados em cada projeto local.</p><span class="status">Implementado no workspace</span></article><article class="card"><div class="icon">⌁</div><h3>Servidor e acesso privado</h3><p>Backend, autorização por projeto, cofre de chaves e auditoria de acesso previstos para a versão de produção.</p><span class="status pending">Arquitetura pendente</span></article></div><section class="panel"><h2>O que a criptografia protege</h2><p>O backup criptografado protege o conteúdo do arquivo enquanto está fechado. Os dados usados na sessão do editor e o armazenamento local desta versão permanecem acessíveis a quem tem acesso a este navegador.</p><p>HTML, CSS, JavaScript, imagens exibidas e fontes entregues ao visitante podem ser inspecionados. Não existe bloqueio absoluto de cópia da aparência. Regras e credenciais que precisam permanecer privadas devem rodar no servidor.</p><p>Não há chaves de API embutidas nem bibliotecas do Sphere incorporadas neste protótipo. A integração com 3DVista e o licenciamento das fontes de cada cliente exigem validação própria.</p><a href="https://cheatsheetseries.owasp.org/cheatsheets/Web_Frontend_Security_Cheat_Sheet.html" target="_blank" rel="noopener noreferrer">Referência: OWASP · segurança do frontend ↗</a></section>`;bind('security-export','click',encryptedBackupForm);}
function bytesTo64(bytes){let s='';for(let i=0;i<bytes.length;i+=8192)s+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(s)}
function from64(s){const text=atob(s),out=new Uint8Array(text.length);for(let i=0;i<text.length;i++)out[i]=text.charCodeAt(i);return out}
async function passwordKey(password,salt,usage){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:600000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,usage)}
async function encryptBackup(data,password){const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await passwordKey(password,salt,['encrypt']);const encrypted=await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:new TextEncoder().encode('mgtour360.backup/v1')},key,new TextEncoder().encode(JSON.stringify(data)));return{schema:'mgtour360.encrypted-backup/v1',algorithm:'AES-GCM',keyBits:256,kdf:'PBKDF2-SHA256',iterations:600000,salt:bytesTo64(salt),iv:bytesTo64(iv),ciphertext:bytesTo64(new Uint8Array(encrypted))}}
async function decryptBackup(packet,password){if(packet.schema!=='mgtour360.encrypted-backup/v1'||packet.algorithm!=='AES-GCM'||packet.kdf!=='PBKDF2-SHA256'||packet.iterations!==600000)throw Error('Envelope criptográfico inválido.');const salt=from64(packet.salt),iv=from64(packet.iv);if(salt.length!==16||iv.length!==12)throw Error('Parâmetros inválidos.');const key=await passwordKey(password,salt,['decrypt']);const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv,additionalData:new TextEncoder().encode('mgtour360.backup/v1')},key,from64(packet.ciphertext));return JSON.parse(new TextDecoder().decode(plain))}
function encryptedBackupForm(){modal(`<h2>Backup criptografado.</h2><p>Escolha uma senha longa e guarde-a em local seguro. Sem ela, este arquivo não poderá ser recuperado. A senha não será salva pelo programa.</p><form id="encrypted-backup-form" class="formgrid">${field('Senha — mínimo de 12 caracteres','backup-pass','','password','required minlength="12" maxlength="200" autocomplete="new-password"')}${field('Repita a senha','backup-pass-repeat','','password','required minlength="12" maxlength="200" autocomplete="new-password"')}<div class="full"><button class="dark" type="submit">Criptografar e baixar</button></div></form>`);bind('encrypted-backup-form','submit',async e=>{e.preventDefault();const password=$('#backup-pass').value;if(password!==$('#backup-pass-repeat').value)return toast('As senhas precisam ser iguais.');const btn=e.submitter;btn.disabled=true;toast('Criptografando o backup...');try{const packet=await encryptBackup(state,password);download('mg-tour-backup.mgtour',JSON.stringify(packet));closeModal();toast('Arquivo protegido gerado. Guarde sua senha.')}catch(err){toast('Falha ao proteger backup: '+err.message);btn.disabled=false}})}
async function decodeBackupFile(file){if(file.size>512*1024*1024)throw Error('Backup excede o limite local de 512 MB.');const data=JSON.parse(await file.text());if(data.schema!=='mgtour360.encrypted-backup/v1')return validateWorkspaceData(data);return new Promise((resolve,reject)=>{modal(`<h2>Abrir backup protegido.</h2><p>A senha só será usada para abrir este arquivo.</p><form id="unlock-backup">${field('Senha do backup','unlock-pass','','password','required autocomplete="off"')}<br><button type="submit" class="dark">Descriptografar</button></form>`);bind('unlock-backup','submit',async e=>{e.preventDefault();try{const decoded=validateWorkspaceData(await decryptBackup(data,$('#unlock-pass').value));closeModal();resolve(decoded)}catch{toast('Senha incorreta ou arquivo alterado. Nenhum dado foi restaurado.')}});$('#modal').addEventListener('cancel',()=>reject(Error('Restauração cancelada.')),{once:true});})}
const baseSkinLibrary=renderSkinLibrary;
renderSkinLibrary=function(root){baseSkinLibrary(root);const button=document.createElement('button');button.id='create-new-skin';button.className='dark';button.textContent='+ Criar nova skin';button.onclick=skinComposer;root.querySelector('.my-skins .actions').prepend(button)};
function skinComposer(){const first=skinById(project()?.layoutId);modal(`<div class="eyebrow">BIBLIOTECA EM EVOLUÇÃO</div><h2>Crie uma nova composição.</h2><p>Parta de um modelo e ajuste a posição dos blocos. O novo layout fica na sua coleção, sem dados de clientes.</p><form id="skin-composer"><div class="formgrid">${field('Nome da nova skin *','compose-name','','text','required maxlength="80"')}<label>Composição de partida<select id="compose-base">${MG_SKINS.map(s=>`<option value="${s.id}" ${s.id===first.id?'selected':''}>${s.name}</option>`).join('')}</select></label>${field('Cor do painel','compose-panel',first.panel,'color')}${field('Cor de destaque','compose-color',first.color,'color')}${field('Opacidade (%)','compose-opacity',85,'number','min="25" max="100"')}${field('Desfoque (px)','compose-blur',10,'number','min="0" max="24"')}${field('Cantos (px)','compose-radius',first.radius,'number','min="0" max="24"')}</div><div id="composer-preview" class="layout-thumb composer-preview"></div><h3>Posição dos blocos em porcentagem</h3><p class="muted">X e Y indicam o canto superior esquerdo. Cada bloco precisa permanecer dentro dos 100% da área.</p><div class="table-wrap"><table class="composer-table"><thead><tr><th>Bloco</th><th>X</th><th>Y</th><th>Largura</th><th>Altura</th></tr></thead><tbody>${['brand','scene','dock','menu'].map((key,i)=>`<tr><th>${['Marca','Ambiente','Controles','Menu'][i]}</th>${first.layout[key].map((v,n)=>`<td><input type="number" data-compose="${key}:${n}" aria-label="${['Marca','Ambiente','Controles','Menu'][i]} ${['X','Y','Largura','Altura'][n]}" min="0" max="100" step="1" value="${v}" required></td>`).join('')}</tr>`).join('')}</tbody></table></div><p id="compose-validation" class="muted"></p><button class="dark" type="submit">Adicionar à minha coleção</button></form>`);function current(){const layout={};for(const key of['brand','scene','dock','menu'])layout[key]=[0,1,2,3].map(n=>Number($(`[data-compose="${key}:${n}"]`).value));return{name:$('#compose-name').value.trim()||'Nova composição',baseId:$('#compose-base').value,layout,panel:$('#compose-panel').value,color:$('#compose-color').value,surface:{opacity:+$('#compose-opacity').value,blur:+$('#compose-blur').value,radius:+$('#compose-radius').value}}}function preview(){try{const candidate=validatePersonalSkin(current());$('#composer-preview').innerHTML=layoutThumb({...skinById(candidate.baseId),id:'custom-preview',name:candidate.name,layout:candidate.layout,panel:candidate.panel,color:candidate.color,radius:candidate.surface.radius});$('#compose-validation').textContent='Composição válida. Confira a sobreposição dos elementos antes de salvar.'}catch(e){$('#compose-validation').textContent=e.message}}bind('compose-base','change',()=>{const s=skinById($('#compose-base').value);for(const key of['brand','scene','dock','menu'])s.layout[key].forEach((v,n)=>$(`[data-compose="${key}:${n}"]`).value=v);$('#compose-panel').value=s.panel;$('#compose-color').value=s.color;$('#compose-radius').value=s.radius;preview()});$$('#skin-composer input').forEach(el=>el.oninput=preview);preview();bind('skin-composer','submit',async e=>{e.preventDefault();if(state.personalSkins.length>=50)return toast('Limite local de 50 skins pessoais. Exporte a coleção antes de reorganizar.');try{const skin=validatePersonalSkin(current());state.personalSkins.push(skin);await save();closeModal();if(activeRoute==='studio')studio();else skinsPage();toast('Nova skin adicionada à sua coleção.')}catch(err){toast('Revise a composição: '+err.message)}})}

function validateWorkspaceData(data){
 if(!data||data.version!==1||!Array.isArray(data.projects)||!Array.isArray(data.leads)||!Array.isArray(data.catalog)||!Array.isArray(data.briefings))throw Error('Estrutura de backup inválida.');
 const hex=/^#[0-9a-f]{6}$/i,id=/^[a-zA-Z0-9_-]{1,100}$/,image=/^data:image\/(jpeg|png|webp);base64,[a-zA-Z0-9+/=]+$/;
 const checkId=value=>{if(typeof value!=='string'||!id.test(value))throw Error('Identificador inválido.');};
 const checkBrand=b=>{if(!b||typeof b.name!=='string'||!hex.test(b.color)||typeof b.logo!=='string'||(b.logo&&!image.test(b.logo)))throw Error('Identidade ou logotipo inválido.');};
 checkBrand(data.brand);
 const ids=new Set();
 for(const p of data.projects){checkId(p.id);if(ids.has(p.id))throw Error('Projeto duplicado.');ids.add(p.id);if(typeof p.name!=='string'||typeof p.client!=='string'||!Array.isArray(p.scenes)||!Array.isArray(p.pins))throw Error('Projeto inválido.');if(p.brand)checkBrand(p.brand);if(p.panel&&!hex.test(p.panel))throw Error('Cor de painel inválida.');if(p.floorplan&&!image.test(p.floorplan))throw Error('Planta inválida.');if(p.layout)validatePersonalSkin({name:'Validação',baseId:p.layoutId,layout:p.layout,panel:p.panel||'#132c29',color:p.brand?.color||'#ffffff',surface:p.surface});const scenes=new Set();for(const scene of p.scenes){checkId(scene.id);if(scenes.has(scene.id))throw Error('Cena duplicada.');scenes.add(scene.id);if(typeof scene.name!=='string'||!image.test(scene.image)||!Array.isArray(scene.hotspots)||!Number.isFinite(scene.width)||!Number.isFinite(scene.height)||scene.width<=0||scene.height<=0)throw Error('Cena ou imagem inválida.');for(const h of scene.hotspots){checkId(h.id);if(!['scene','link','info'].includes(h.type)||typeof h.label!=='string'||typeof h.target!=='string'||!Number.isFinite(h.yaw)||!Number.isFinite(h.pitch))throw Error('Ponto inválido.');if(h.type==='link'&&!safeURL(h.target))throw Error('Link de ponto inválido.');}}for(const pin of p.pins){checkId(pin.scene);if(!Number.isFinite(pin.x)||!Number.isFinite(pin.y)||pin.x<0||pin.x>1||pin.y<0||pin.y>1)throw Error('Pino inválido.');}}
 for(const group of[data.leads,data.catalog,data.briefings])for(const item of group)checkId(item.id);
 if(data.personalSkins){if(!Array.isArray(data.personalSkins)||data.personalSkins.length>50)throw Error('Coleção inválida.');data.personalSkins=data.personalSkins.map(validatePersonalSkin)}
 return data;
}
const originalBrandPage=brand;
brand=()=>{originalBrandPage();const description=document.createElement('p');description.className='notice';description.textContent='Esta é a marca da produtora, usada nos módulos comerciais. A identidade de cada cliente é configurada dentro do respectivo projeto.';$('#main').append(description);if(state.brand.logo){const button=document.createElement('button');button.type='button';button.id='clear-workspace-logo';button.textContent='Remover logo da produtora';button.onclick=async()=>{state.brand.logo='';await save();brand();toast('Logo removido desta configuração. O arquivo original foi preservado.');};$('#brand-form').append(button)}};
